    def punishmentNumber(self, n: int) -> int:

        def can_partition(s: str, target: int) -> bool:
            """
            Checks if the string s can be partitioned into contiguous substrings 
            whose integer values sum up to target.
            This is a recursive function with memoization (though memoization 
            is not strictly necessary given the small constraints, it's good practice).
            """
            memo = {}

            def backtrack(index: int, current_sum: int) -> bool:
                if index == len(s):
                    return current_sum == target

                # Optimization: If current_sum already exceeds target, prune this branch
                if current_sum > target:
                    return False

                # Try all possible split points from the current index
                for j in range(index, len(s)):
                    # Extract the substring from index to j (inclusive)
                    substring = s[index : j+1]

                    # Convert the substring to an integer
                    val = int(substring)

                    # Recursive call: move to the next index (j+1) and add the value
                    if backtrack(j + 1, current_sum + val):
                        return True

                return False

            # Start the backtracking from the beginning of the string with sum 0
            return backtrack(0, 0)


        total_punishment = 0

        # Iterate through all numbers from 1 to n
        for i in range(1, n + 1):
            i_squared = i * i
            s_squared = str(i_squared)

            # Check if the square of i can be partitioned to sum up to i
            if can_partition(s_squared, i):
                total_punishment += i_squared

        return total_punishment

