class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        n = len(s)
        max_len = 0

        # Iterate through all possible starting positions of the substring
        for i in range(n):
            # Iterate through all possible ending positions of the substring (j >= i)
            for j in range(i, n):
                # Extract the substring
                sub = s[i : j+1]

                # Check if the substring is semi-repetitive
                if self.is_semi_repetitive(sub):
                    max_len = max(max_len, len(sub))
                else:
                    # Optimization: If the current substring s[i:j+1] is not semi-repetitive,
                    # then any longer substring starting at i (s[i:k+1] where k>j) 
                    # will also not be semi-repetitive.
                    break

        return max_len

    def is_semi_repetitive(self, t: str) -> bool:
        """Checks if a string t is semi-repetitive."""
        consecutive_pairs = 0
        for k in range(len(t) - 1):
            if t[k] == t[k+1]:
                consecutive_pairs += 1
        return consecutive_pairs <= 1

