class Solution:
    def get_max_digit(self, n: int) -> int:
        if n == 0:
            return 0
        max_d = 0
        for digit in str(n):
            digit_int = int(digit)
            if digit_int > max_d:
                max_d = digit_int
        return max_d

    def maxSum(self, nums: List[int]) -> int:
        # Dictionary to store the maximum value found for each maximum digit.
        # Key: maximum digit (0-9)
        # Value: A list of numbers from nums whose maximum digit is the key.
        max_digit_groups = {}

        # 1. Group numbers by their maximum digit
        for num in nums:
            max_d = self.get_max_digit(num)
            if max_d not in max_digit_groups:
                max_digit_groups[max_d] = []
            max_digit_groups[max_d].append(num)

        # 2. Find the maximum sum within each group
        max_total_sum = -1

        for max_d in max_digit_groups:
            group = max_digit_groups[max_d]

            # If a group has at least two numbers, we can form a pair.
            if len(group) >= 2:
                # To maximize the sum of a pair, we need the two largest numbers in the group.
                group.sort(reverse=True)

                # The sum of the two largest elements
                current_sum = group[0] + group[1]

                # Update the overall maximum sum
                if current_sum > max_total_sum:
                    max_total_sum = current_sum

        return max_total_sum

