    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0

        # Iterate through all possible pairs (i, j) where i and j are indices in nums
        # Since we can pick the same integer twice, we check all pairs (nums[i], nums[j])
        for x in nums:
            for y in nums:
