                # |x - y| <= min(x, y)

                # Case 1: x >= y
                if x >= y:
                    # |x - y| = x - y
                    # min(x, y) = y
                    # Condition becomes: x - y <= y  =>  x <= 2y
                    if x <= 2 * y:
                        # (x, y) is a strong pair
                        current_xor = x ^ y
                        if current_xor > max_xor:
