class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)

        # dp[i] will store the minimum number of balanced substrings 
        # needed to partition the prefix s[0:i] (of length i).
        # Initialize with a value larger than any possible result (n + 1).
        dp = [n + 1] * (n + 1)

        # Base case: An empty string requires 0 substrings.
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(i):
                # Check the substring s[j:i]
                substring = s[j:i]
                if self.is_balanced(substring):
                    # If s[j:i] is balanced, we can potentially update dp[i].
                    # The new count would be dp[j] (for the prefix s[0:j]) + 1 (for s[j:i]).
                    dp[i] = min(dp[i], dp[j] + 1)

        return dp[n]

    def is_balanced(self, sub: str) -> bool:
        """Checks if a string is balanced."""
        if not sub:
            return False # An empty string is not considered balanced for this partitioning logic

        counts = {}
        for char in sub:
            counts[char] = counts.get(char, 0) + 1

        # For a string to be balanced, all characters present must have the same count.

        # 1. Check if all counts are the same as the count of the first character.
        first_char_count = 0
        if counts:
            first_char_count = counts[next(iter(counts))]

        # 2. Iterate through the values in the counts dictionary.
        for count in counts.values():
            if count != first_char_count:
                return False

        return True

