from typing import List

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])

        # Calculate the minimum flips to make all rows palindromic
        min_flips_rows = 0
        for i in range(m):
            row = grid[i]
            # For each row, the number of flips needed to make it a palindrome
            # is the number of pairs (j, n-1-j) where grid[i][j] != grid[i][n-1-j]
            flips_in_row = 0
            for j in range(n // 2):
                if row[j] != row[n - 1 - j]:
                    flips_in_row += 1
            min_flips_rows += flips_in_row

        # Calculate the minimum flips to make all columns palindromic
        min_flips_cols = 0
        for j in range(n):
            col = [grid[i][j] for i in range(m)]
            # For each column, the number of flips needed to make it a palindrome
            # is the number of pairs (i, m-1-i) where grid[i][j] != grid[m-1-i][j]
            flips_in_col = 0
            for i in range(m // 2):
                if col[i] != col[m - 1 - i]:
                    flips_in_col += 1
            min_flips_cols += flips_in_col

        # Return the minimum of the two possibilities
        return min(min_flips_rows, min_flips_cols)

