class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Initial position is cell 0.
        # In an n x n grid, cell 0 is at (row, col) = (0, 0).

        # We need to track the current row (r) and column (c).
        r, c = 0, 0

        for command in commands:
            if command == "UP":
                r -= 1
            elif command == "DOWN":
                r += 1
            elif command == "LEFT":
                c -= 1
            elif command == "RIGHT":
                c += 1

        # After all movements, the final position is (r, c).
        # The cell value is calculated as (r * n) + c.
        return (r * n) + c

