class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')
        n = len(word)
        count = 0

        # Iterate through all possible start indices of the substring
        for i in range(n):
            # Check the substring starting at i and expanding to j
            for j in range(i, n):
                substring = word[i:j+1]

                # 1. Check for all vowels
                has_all_vowels = True
                present_vowels = set()
                for char in substring:
                    if char in vowels:
                        present_vowels.add(char)

                if len(present_vowels) != 5:
                    continue

                # 2. Check for exactly k consonants
                consonant_count = 0
                for char in substring:
                    if char not in vowels:
                        consonant_count += 1

                if consonant_count == k:
                    count += 1

        return count
