class Solution:
    def minElement(self, nums: List[int]) -> int:
        # Function to calculate the sum of digits of a number
        def sum_digits(n: int) -> int:
            s = 0
            while n:
                s += n % 10
                n //= 10
            return s

        # Step 1: Replace each element in nums with the sum of its digits
        new_nums = []
        for num in nums:
            new_nums.append(sum_digits(num))

        # Step 2: Return the minimum element in the new array
        return min(new_nums)

